def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify separate groups of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced by counting the number of open and close parentheses
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    # Step 4: Add each balanced group to a list while ensuring it is distinct
    distinct_groups = []
    for group in groups:
        if is_balanced(group) and group not in distinct_groups:
            distinct_groups.append(group)

    # Step 5: Return the list of distinct groups
    return distinct_groups
